using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain the static queue to avoid cross-test interference
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue after each test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForCreate()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForUpdate()
    {
        _sut.SendNotification("Course", "42", "Chemistry", EntityOperation.UPDATE, "teacher");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
        Assert.Equal("teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForDelete()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "admin");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdFormat()
    {
        _sut.SendNotification("Student", "99", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 99) has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_NullDisplayName_UsesIdFormat()
    {
        _sut.SendNotification("Student", "7", null, EntityOperation.UPDATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 7) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_EmptyDisplayName_UsesIdFormat()
    {
        _sut.SendNotification("Student", "7", "  ", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 7) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_DequeusFIFO()
    {
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.Equal("A", first.EntityType);
        Assert.Equal("B", second.EntityType);
    }

    [Fact]
    public void ReceiveNotification_RemovesFromQueue()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.Null(second);
    }

    [Fact]
    public void SendNotification_QueueCapAt500_OldestEvicted()
    {
        // Send 505 notifications
        for (int i = 0; i < 505; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Count remaining
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;
        Assert.True(count <= 500, $"Queue should be capped at 500, but had {count}");
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation
        var exception = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void MarkAsRead_NonExistentId_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
