using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;
    private readonly NotificationService _service;

    public NotificationsControllerTests()
    {
        _context = TestDbHelper.CreateContext();
        _service = new NotificationService();
        // Drain static queue
        while (_service.ReceiveNotification() != null) { }
        _controller = new NotificationsController(_context);
    }

    public void Dispose()
    {
        // Drain queue
        while (_service.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
        _service.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        dynamic value = result.Value;
        var type = result.Value.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        Assert.True((bool)successProp.GetValue(result.Value));
        Assert.Equal(0, (int)countProp.GetValue(result.Value));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsThemAll()
    {
        // Enqueue some notifications via the static queue
        _service.SendNotification("Student", "1", "John", EntityOperation.CREATE);
        _service.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

        var result = _controller.GetNotifications();

        var type = result.Value.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        var notificationsProp = type.GetProperty("notifications");

        Assert.True((bool)successProp.GetValue(result.Value));
        Assert.Equal(2, (int)countProp.GetValue(result.Value));
        var notifications = (List<Notification>)notificationsProp.GetValue(result.Value);
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("Course", notifications[1].EntityType);
    }

    [Fact]
    public void GetNotifications_LimitsTo10()
    {
        for (int i = 0; i < 15; i++)
        {
            _service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        var result = _controller.GetNotifications();

        var type = result.Value.GetType();
        var countProp = type.GetProperty("count");
        Assert.Equal(10, (int)countProp.GetValue(result.Value));
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        Assert.IsType<JsonResult>(result);
        var type = result.Value.GetType();
        var successProp = type.GetProperty("success");
        Assert.True((bool)successProp.GetValue(result.Value));
    }
}

