using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;
    private readonly NotificationService _drainer;

    public StudentsControllerTests()
    {
        _context = TestDbHelper.CreateContext();
        _drainer = new NotificationService();
        while (_drainer.ReceiveNotification() != null) { }
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        while (_drainer.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
        _drainer.Dispose();
    }

    private Student SeedStudent(string first = "John", string last = "Doe", string date = "2020-09-01")
    {
        var student = new Student
        {
            FirstMidName = first,
            LastName = last,
            EnrollmentDate = DateTime.Parse(date)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    private void SeedMultipleStudents()
    {
        _context.Students.AddRange(
            new Student { FirstMidName = "Alice", LastName = "Adams", EnrollmentDate = DateTime.Parse("2020-01-01") },
            new Student { FirstMidName = "Bob", LastName = "Brown", EnrollmentDate = DateTime.Parse("2021-06-15") },
            new Student { FirstMidName = "Charlie", LastName = "Clark", EnrollmentDate = DateTime.Parse("2019-09-01") }
        );
        _context.SaveChanges();
    }

    // --- Index ---

    [Fact]
    public void Index_DefaultSort_ReturnsByLastNameAscending()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Adams", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
    }

    [Fact]
    public void Index_NameDesc_ReturnsByLastNameDescending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("name_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Clark", model[0].LastName);
        Assert.Equal("Brown", model[1].LastName);
        Assert.Equal("Adams", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsByDateAscending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("Date", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Clark", model[0].LastName); // 2019
        Assert.Equal("Adams", model[1].LastName); // 2020
        Assert.Equal("Brown", model[2].LastName); // 2021
    }

    [Fact]
    public void Index_DateDescSort_ReturnsByDateDescending()
    {
        SeedMultipleStudents();

        var result = _controller.Index("date_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Brown", model[0].LastName); // 2021
        Assert.Equal("Adams", model[1].LastName); // 2020
        Assert.Equal("Clark", model[2].LastName); // 2019
    }

    [Fact]
    public void Index_SearchByLastName_FiltersResults()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Brown", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Brown", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersResults()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Alice", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Adams", model[0].LastName);
    }

    [Fact]
    public void Index_SearchNoMatch_ReturnsEmpty()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "ZZZ", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void Index_NewSearch_ResetsPage()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, null, "Adams", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_CurrentFilter_PreservedWhenNoNewSearch()
    {
        SeedMultipleStudents();

        var result = _controller.Index(null, "Adams", null, 1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_SetsViewBagSortParams()
    {
        var result = _controller.Index(null, null, null, null);

        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_NameSortActive_TogglesToDefault()
    {
        var result = _controller.Index("name_desc", null, null, null);

        Assert.Equal("", _controller.ViewBag.NameSortParm);
    }

    [Fact]
    public void Index_DateSortActive_TogglesToDateDesc()
    {
        var result = _controller.Index("Date", null, null, null);

        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsStudent()
    {
        var student = SeedStudent();
        // Add an enrollment with course for the Include
        var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();
        _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 100, Grade = Grade.A });
        _context.SaveChanges();

        var result = _controller.Details(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Doe", model.LastName);
        Assert.Equal("John", model.FirstMidName);
    }

    // --- Create GET ---

    [Fact]
    public void Create_Get_ReturnsViewWithStudent_DefaultDate()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // --- Create POST ---

    [Fact]
    public void CreatePost_ValidStudent_SavesAndRedirects()
    {
        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Single(_context.Students);
        Assert.Equal("Smith", _context.Students.First().LastName);
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student { EnrollmentDate = DateTime.Parse("2023-01-01") };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Student>(viewResult.Model);
    }

    [Fact]
    public void CreatePost_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_DateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void CreatePost_ValidStudent_SendsNotification()
    {
        // Drain first
        while (_drainer.ReceiveNotification() != null) { }

        var student = new Student
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            EnrollmentDate = DateTime.Parse("2023-09-01")
        };

        _controller.Create(student);

        var notification = _drainer.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Contains("Jane Smith", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    // --- Edit GET ---

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_MissingId_ReturnsNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithStudent()
    {
        var student = SeedStudent();

        var result = _controller.Edit(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Doe", model.LastName);
    }

    // --- Edit POST ---

    [Fact]
    public void EditPost_ValidStudent_SavesAndRedirects()
    {
        var student = SeedStudent();
        _context.Entry(student).State = EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Updated",
            LastName = "Name",
            EnrollmentDate = DateTime.Parse("2023-01-01")
        };

        var result = _controller.Edit(updatedStudent);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_MinValueDate_AddsModelError()
    {
        var student = SeedStudent();
        _context.Entry(student).State = EntityState.Detached;

        var updatedStudent = new Student
        {
            ID = student.ID,
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(updatedStudent);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    // --- Delete GET ---

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_MissingId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
