    public DepartmentsControllerTests()
    {
        _context = TestDbHelper.CreateContext();
        _drainer = new NotificationService();
        while (_drainer.ReceiveNotification() != null) { }
        _controller = new DepartmentsController(_context);
    }

    public void Dispose()
    {
        while (_drainer.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
        _drainer.Dispose();
    }

    private Instructor SeedInstructor(string first = "Kim", string last = "Abercrombie")
    {
        var instructor = new Instructor
        {
            FirstMidName = first,
            LastName = last,
            HireDate = DateTime.Parse("2000-01-01")
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", Instructor admin = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000m,
            StartDate = DateTime.Parse("2020-09-01"),
            InstructorID = admin?.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    // --- Index ---

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        var instructor = SeedInstructor();
        SeedDepartment("Math", instructor);
        SeedDepartment("Science", instructor);

        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_EmptyDb_ReturnsEmptyList()
    {
        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Empty(model);
    }

