        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { StartDate = DateTime.Now };

        var result = _controller.Edit(dept);

        Assert.IsType<ViewResult>(result);
    }

    // --- Delete GET ---

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_MissingId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithDepartment()
    {
        var dept = SeedDepartment();

        var result = _controller.Delete(dept.DepartmentID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Engineering", model.Name);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesAndRedirects()
    {
        var dept = SeedDepartment();

        var result = _controller.DeleteConfirmed(dept.DepartmentID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Departments);
    }

    [Fact]
    public void DeleteConfirmed_SendsNotification()
    {
        while (_drainer.ReceiveNotification() != null) { }
        var dept = SeedDepartment("Chemistry");

        _controller.DeleteConfirmed(dept.DepartmentID);

        var notification = _drainer.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department", notification.EntityType);
        Assert.Contains("deleted", notification.Message);
    }
}

