    [Fact]
    public void CreatePost_ValidNoImage_SavesAndRedirects()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 2000,
            Title = "Algebra",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Single(_context.Courses);
        Assert.Equal("Algebra", _context.Courses.First().Title);
    }

    [Fact]
    public void CreatePost_WithValidImage_SavesCourseWithImagePath()
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 2001,
            Title = "Art",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };
        var fileMock = CreateMockFile("picture.png", 2048);

        var result = _controller.Create(course, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var savedCourse = _context.Courses.First();
        Assert.StartsWith("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
        Assert.Contains(".png", savedCourse.TeachingMaterialImagePath);
    }

