        var result = _controller.Create(course, null);

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void CreatePost_SendsNotification()
    {
        while (_drainer.ReceiveNotification() != null) { }
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 3000,
            Title = "Biology",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        _controller.Create(course, null);

        var notification = _drainer.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Contains("Biology", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void CreatePost_AllowedExtensions_Accepted(string ext)
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 5000 + ext.GetHashCode() % 1000,
            Title = "Test",
            Credits = 1,
            DepartmentID = dept.DepartmentID
        };
        var fileMock = CreateMockFile($"image{ext}", 1024);

        var result = _controller.Create(course, fileMock.Object);

        Assert.IsType<RedirectToActionResult>(result);
    }

    // --- Edit GET ---

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_MissingId_ReturnsNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Edit(course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    // --- Edit POST ---

    [Fact]
    public void EditPost_ValidNoImage_SavesAndRedirects()
    {
        var course = SeedCourse();
        _context.Entry(course).State = EntityState.Detached;

        var updated = new Course
        {
            CourseID = course.CourseID,
            Title = "Advanced Chemistry",
            Credits = 4,
            DepartmentID = course.DepartmentID
        };

        var result = _controller.Edit(updated, null);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course();

        var result = _controller.Edit(course, null);

        Assert.IsType<ViewResult>(result);
    }

    // --- Delete GET ---

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithCourse()
    {
        var course = SeedCourse();

        var result = _controller.Delete(course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    // --- DeleteConfirmed ---

    [Fact]
    public void DeleteConfirmed_RemovesCourseAndRedirects()
    {
        var course = SeedCourse();

        var result = _controller.DeleteConfirmed(course.CourseID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Courses);
    }

    [Fact]
    public void DeleteConfirmed_SendsNotification()
    {
        while (_drainer.ReceiveNotification() != null) { }
        var course = SeedCourse(7777, "Physics");

        _controller.DeleteConfirmed(course.CourseID);

        var notification = _drainer.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Contains("deleted", notification.Message);
    }
}

