        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        while (_drainer.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
        _drainer.Dispose();
    }

    private Instructor SeedInstructor(string first = "Kim", string last = "Abercrombie")
    {
        var instructor = new Instructor
        {
            FirstMidName = first,
            LastName = last,
            HireDate = DateTime.Parse("2000-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", int? instructorId = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000m,
            StartDate = DateTime.Parse("2020-01-01"),
            InstructorID = instructorId
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course SeedCourse(int id = 1050, string title = "Chemistry", Department dept = null)
    {
        dept ??= SeedDepartment();
        var course = new Course
        {
            CourseID = id,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID,
            Enrollments = new List<Enrollment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // --- Index ---

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        SeedInstructor("Kim", "Abercrombie");
        SeedInstructor("Roger", "Harui");

        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructor = SeedInstructor();
        var dept = SeedDepartment();
        var course = SeedCourse(1050, "Chemistry", dept);
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        });
        _context.SaveChanges();

        var result = _controller.Index(instructor.ID, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Chemistry", model.Courses.First().Title);
    }

    [Fact]
    public void Index_EmptyDb_ReturnsEmptyInstructors()
    {
        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.Empty(model.Instructors);
    }

    // --- Details ---

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_MissingId_ReturnsNotFound()
    {
