    [Fact]
    public void CreatePost_ValidInstructor_SavesAndRedirects()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Prof",
            HireDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Create(instructor, null);

