using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_SeedsStudents()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsInstructors()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsDepartments()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourses()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsEnrollments()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_SkipsIfDataExists()
    {
        using var context = TestDbHelper.CreateContext();

        // Pre-seed one student
        context.Students.Add(new Student
        {
            FirstMidName = "Existing",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2020-01-01")
        });
        context.SaveChanges();

        DbInitializer.Initialize(context);

        // Should still have just the one student
        Assert.Single(context.Students);
        Assert.Equal("Existing", context.Students.First().FirstMidName);
    }

    [Fact]
    public void Initialize_CalledTwice_DoesNotDuplicate()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);
        DbInitializer.Initialize(context);

        // Second call should be no-op since students exist
        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsCorrectStudentNames()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        var lastNames = context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
        Assert.Contains("Alexander", lastNames);
        Assert.Contains("Alonso", lastNames);
        Assert.Contains("Anand", lastNames);
        Assert.Contains("Barzdukas", lastNames);
        Assert.Contains("Li", lastNames);
        Assert.Contains("Justice", lastNames);
        Assert.Contains("Norman", lastNames);
        Assert.Contains("Olivetto", lastNames);
    }

    [Fact]
    public void Initialize_SeedsCorrectDepartmentNames()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        var names = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
        Assert.Equal(new[] { "Economics", "Engineering", "English", "Mathematics" }, names);
    }

    [Fact]
    public void Initialize_EnrollmentsHaveGrades()
    {
        using var context = TestDbHelper.CreateContext();

        DbInitializer.Initialize(context);

        var withGrades = context.Enrollments.Count(e => e.Grade != null);
        var withoutGrades = context.Enrollments.Count(e => e.Grade == null);
        Assert.True(withGrades > 0, "Some enrollments should have grades");
        Assert.True(withoutGrades > 0, "Some enrollments should have no grade");
    }
}

